bam_error F_ac4_variable_bits_reset(struct BAMSyntax * BAM_Syntax)
{
    err = reset_state(BAM_Syntax);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
bam_error F_ac4_variable_bits_set_input(struct BAMSyntax * BAM_Syntax, struct BAMVector * param_vector)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_Syntax;
    (void) bamsyntax;
    bamsyntax->BAM_user_args = param_vector;
    return BAM_OK;
}
bam_error F_ac4_variable_bits_parse_generic(struct BAMSyntax * BAM_syntax, struct BAMSource * BAM_source, struct BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    bam_error err;
    err = F_ac4_variable_bits_parse(&BAM_syntax->BAM_result, BAM_syntax, BAMParameter_as_int(BAMVector_data_parameter(bamsyntax->BAM_user_args)[0]), BAM_source, BAM_sink);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
BAMint F_ac4_variable_bits_get_result(struct BAMSyntax * BAM_syntax)
{
    return BAM_syntax->BAM_result;
}
bam_error F_ac4_variable_bits_parse(BAMint * BAM_result, BAMSyntax  * BAM_syntax, BAMint ac4_n_bits, BAMSource * BAM_source, BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    BAMint ac4_value;
    BAMint ac4_b_read_more;
    BAMint ac4_read;
    int BAM_bool;

    (void) BAM_bool;
    {
        ac4_value = 0;
        err = BAM_sink->after_assign_int(BAM_sink,"value", ac4_value);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    {
        ac4_b_read_more = 1;
        err = BAM_sink->after_assign_int(BAM_sink,"b_read_more", ac4_b_read_more);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    while (ac4_b_read_more)
    {
        {
            err = BAM_source->read_uint(BAM_source, ac4_n_bits, &ac4_read);
            if (err != BAM_OK)
            {
                return err;
            }
            bamsyntax->BAM_g_position += ac4_n_bits;
            err = BAM_sink->write_uint(BAM_sink, "read", ac4_n_bits, ac4_read);
            if (err != BAM_OK)
            {
                return err;
            }
        }
        {
            ac4_value += ac4_read;
            err = BAM_sink->after_assign_int(BAM_sink,"value", ac4_value);
            if (err != BAM_OK)
            {
                return err;
            }
        }
        {
            err = BAM_source->read_uint(BAM_source, 1, &ac4_b_read_more);
            if (err != BAM_OK)
            {
                return err;
            }
            bamsyntax->BAM_g_position += 1;
            err = BAM_sink->write_uint(BAM_sink, "b_read_more", 1, ac4_b_read_more);
            if (err != BAM_OK)
            {
                return err;
            }
        }
        if (ac4_b_read_more)
        {
            {
                {
                    ac4_value <<= ac4_n_bits;
                    err = BAM_sink->after_assign_int(BAM_sink,"value", ac4_value);
                    if (err != BAM_OK)
                    {
                        return err;
                    }
                }
                {
                    ac4_value += 1 << ac4_n_bits;
                    err = BAM_sink->after_assign_int(BAM_sink,"value", ac4_value);
                    if (err != BAM_OK)
                    {
                        return err;
                    }
                }
            }
        }
    }
    *BAM_result =  ac4_value;
    {
    }
    return BAM_OK;
    return BAM_OK;
}

