bam_error F_ac4_presentation_version_reset(struct BAMSyntax * BAM_Syntax)
{
    err = reset_state(BAM_Syntax);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
bam_error F_ac4_presentation_version_set_input(struct BAMSyntax * BAM_Syntax, struct BAMVector * param_vector)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_Syntax;
    (void) bamsyntax;
    bamsyntax->BAM_user_args = param_vector;
    return BAM_OK;
}
bam_error F_ac4_presentation_version_parse_generic(struct BAMSyntax * BAM_syntax, struct BAMSource * BAM_source, struct BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    bam_error err;
    err = F_ac4_presentation_version_parse(&BAM_syntax->BAM_result, BAM_syntax, BAM_source, BAM_sink);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
BAMint F_ac4_presentation_version_get_result(struct BAMSyntax * BAM_syntax)
{
    return BAM_syntax->BAM_result;
}
bam_error F_ac4_presentation_version_parse(BAMint * BAM_result, BAMSyntax  * BAM_syntax, BAMSource * BAM_source, BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    BAMint ac4_val;
    BAMint ac4_b_tmp;
    int BAM_bool;

    (void) BAM_bool;
    {
        ac4_val = 0;
        err = BAM_sink->after_assign_int(BAM_sink,"val", ac4_val);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    {
        err = BAM_source->read_uint(BAM_source, 1, &ac4_b_tmp);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 1;
        err = BAM_sink->write_uint(BAM_sink, "b_tmp", 1, ac4_b_tmp);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    while (ac4_b_tmp)
    {
        {
            ac4_val = ac4_val + 1;
            err = BAM_sink->after_assign_int(BAM_sink,"val", ac4_val);
            if (err != BAM_OK)
            {
                return err;
            }
        }
        {
            err = BAM_source->read_uint(BAM_source, 1, &ac4_b_tmp);
            if (err != BAM_OK)
            {
                return err;
            }
            bamsyntax->BAM_g_position += 1;
            err = BAM_sink->write_uint(BAM_sink, "b_tmp", 1, ac4_b_tmp);
            if (err != BAM_OK)
            {
                return err;
            }
        }
    }
    *BAM_result =  ac4_val;
    {
    }
    return BAM_OK;
    return BAM_OK;
}

