bam_error F_ac4_frame_rate_multiply_info_parse(BAMSyntax  * BAM_syntax, BAMSource * BAM_source, BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    BAMint ac4_b_multiplier;
    BAMint ac4_multiplier_bit;
    int BAM_bool;

    (void) BAM_bool;
    struct BAMVector * BAM_g_table7= BAMVector_create(sizeof(BAMint), 0);
    err = BAMVector_push_vector_int(BAM_g_table7, 2);
    if (err != BAM_OK)
    {
        return err;
    }
    err = BAMVector_push_vector_int(BAM_g_table7, 3);
    if (err != BAM_OK)
    {
        return err;
    }
    err = BAMVector_push_vector_int(BAM_g_table7, 4);
    if (err != BAM_OK)
    {
        return err;
    }
    struct BAMMap * BAM_g_table8 = BAMMap_create(sizeof(BAMint), sizeof(BAMint));
    err = BAMMap_insert_int_int(BAM_g_table8, 0, 2);
    if (err != BAM_OK)
    {
        return err;
    }
    err = BAMMap_insert_int_int(BAM_g_table8, 1, 4);
    if (err != BAM_OK)
    {
        return err;
    }
    struct BAMVector * BAM_g_table9= BAMVector_create(sizeof(BAMint), 0);
    err = BAMVector_push_vector_int(BAM_g_table9, 0);
    if (err != BAM_OK)
    {
        return err;
    }
    err = BAMVector_push_vector_int(BAM_g_table9, 1);
    if (err != BAM_OK)
    {
        return err;
    }
    err = BAMVector_push_vector_int(BAM_g_table9, 7);
    if (err != BAM_OK)
    {
        return err;
    }
    err = BAMVector_push_vector_int(BAM_g_table9, 8);
    if (err != BAM_OK)
    {
        return err;
    }
    err = BAMVector_push_vector_int(BAM_g_table9, 9);
    if (err != BAM_OK)
    {
        return err;
    }
    struct BAMMap * BAM_g_table10 = BAMMap_create(sizeof(BAMint), sizeof(BAMint));
    err = BAMMap_insert_int_int(BAM_g_table10, 0, 1);
    if (err != BAM_OK)
    {
        return err;
    }
    err = BAMMap_insert_int_int(BAM_g_table10, 1, 2);
    if (err != BAM_OK)
    {
        return err;
    }
    struct BAMVector * BAM_l_tmp_vector7 = BAMVector_create(sizeof(BAMint), 0);
    (void) BAM_l_tmp_vector7;
    struct BAMVector * BAM_l_tmp_vector8 = BAMVector_create(sizeof(BAMint), 0);
    (void) BAM_l_tmp_vector8;
    if (BAMVector_find(BAM_g_table7, bamsyntax->ac4_frame_rate_index))
    {
        {
            {
                err = BAM_source->read_uint(BAM_source, 1, &ac4_b_multiplier);
                if (err != BAM_OK)
                {
                    return err;
                }
                bamsyntax->BAM_g_position += 1;
                err = BAM_sink->write_uint(BAM_sink, "b_multiplier", 1, ac4_b_multiplier);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            if (ac4_b_multiplier)
            {
                {
                    {
                        err = BAM_source->read_uint(BAM_source, 1, &ac4_multiplier_bit);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                        bamsyntax->BAM_g_position += 1;
                        err = BAM_sink->write_uint(BAM_sink, "multiplier_bit", 1, ac4_multiplier_bit);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                    }
                    {
                        bamsyntax->ac4_frame_rate_factor = BAMMap_get_int(BAM_g_table8, ac4_multiplier_bit);
                        err = BAM_sink->after_assign_int(BAM_sink,"frame_rate_factor", bamsyntax->ac4_frame_rate_factor);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                    }
                }
            }
            else
            {
                bamsyntax->ac4_frame_rate_factor = 1;
                err = BAM_sink->after_assign_int(BAM_sink,"frame_rate_factor", bamsyntax->ac4_frame_rate_factor);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
        }
    }
    else
    if (BAMVector_find(BAM_g_table9, bamsyntax->ac4_frame_rate_index))
    {
        {
            {
                err = BAM_source->read_uint(BAM_source, 1, &ac4_b_multiplier);
                if (err != BAM_OK)
                {
                    return err;
                }
                bamsyntax->BAM_g_position += 1;
                err = BAM_sink->write_uint(BAM_sink, "b_multiplier", 1, ac4_b_multiplier);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                bamsyntax->ac4_frame_rate_factor = BAMMap_get_int(BAM_g_table10, ac4_b_multiplier);
                err = BAM_sink->after_assign_int(BAM_sink,"frame_rate_factor", bamsyntax->ac4_frame_rate_factor);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
        }
    }
    else
    {
        bamsyntax->ac4_frame_rate_factor = 1;
        err = BAM_sink->after_assign_int(BAM_sink,"frame_rate_factor", bamsyntax->ac4_frame_rate_factor);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    BAMVector_destroy(BAM_l_tmp_vector7, 1);
    BAMVector_destroy(BAM_l_tmp_vector8, 1);
    BAMVector_destroy(BAM_g_table7, 1);
    BAMMap_destroy(BAM_g_table8);
    BAMVector_destroy(BAM_g_table9, 1);
    BAMMap_destroy(BAM_g_table10);
    return BAM_OK;
}

