bam_error F_ac4_channel_mode_reset(struct BAMSyntax * BAM_Syntax)
{
    err = reset_state(BAM_Syntax);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
bam_error F_ac4_channel_mode_set_input(struct BAMSyntax * BAM_Syntax, struct BAMVector * param_vector)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_Syntax;
    (void) bamsyntax;
    bamsyntax->BAM_user_args = param_vector;
    return BAM_OK;
}
bam_error F_ac4_channel_mode_parse_generic(struct BAMSyntax * BAM_syntax, struct BAMSource * BAM_source, struct BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    bam_error err;
    err = F_ac4_channel_mode_parse(&BAM_syntax->BAM_result, BAM_syntax, BAM_source, BAM_sink);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
BAMint F_ac4_channel_mode_get_result(struct BAMSyntax * BAM_syntax)
{
    return BAM_syntax->BAM_result;
}
bam_error F_ac4_channel_mode_parse(BAMint * BAM_result, BAMSyntax  * BAM_syntax, BAMSource * BAM_source, BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    BAMint ac4_value;
    int BAM_bool;

    (void) BAM_bool;
    {
        err = BAM_source->read_uint(BAM_source, 1, &ac4_value);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 1;
        err = BAM_sink->write_uint(BAM_sink, "value", 1, ac4_value);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    if (ac4_value == 1)
    {
        {
            {
                err = BAM_source->read_uint(BAM_source, 1, &bamsyntax->ac4_v);
                if (err != BAM_OK)
                {
                    return err;
                }
                bamsyntax->BAM_g_position += 1;
                err = BAM_sink->write_uint(BAM_sink, "v", 1, bamsyntax->ac4_v);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                ac4_value = (ac4_value << 1) + bamsyntax->ac4_v;
                err = BAM_sink->after_assign_int(BAM_sink,"value", ac4_value);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                bamsyntax->ac4_stereo_channel_mode = 2;
                err = BAM_sink->after_assign_int(BAM_sink,"stereo_channel_mode", bamsyntax->ac4_stereo_channel_mode);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            if (ac4_value == 3)
            {
                {
                    {
                        err = BAM_source->read_uint(BAM_source, 2, &bamsyntax->ac4_v);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                        bamsyntax->BAM_g_position += 2;
                        err = BAM_sink->write_uint(BAM_sink, "v", 2, bamsyntax->ac4_v);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                    }
                    {
                        ac4_value = (ac4_value << 2) + bamsyntax->ac4_v;
                        err = BAM_sink->after_assign_int(BAM_sink,"value", ac4_value);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                    }
                    if (ac4_value == 15)
                    {
                        {
                            {
                                err = BAM_source->read_uint(BAM_source, 3, &bamsyntax->ac4_v);
                                if (err != BAM_OK)
                                {
                                    return err;
                                }
                                bamsyntax->BAM_g_position += 3;
                                err = BAM_sink->write_uint(BAM_sink, "v", 3, bamsyntax->ac4_v);
                                if (err != BAM_OK)
                                {
                                    return err;
                                }
                            }
                            {
                                ac4_value = (ac4_value << 3) + bamsyntax->ac4_v;
                                err = BAM_sink->after_assign_int(BAM_sink,"value", ac4_value);
                                if (err != BAM_OK)
                                {
                                    return err;
                                }
                            }
                            if (ac4_value == 120 || ac4_value == 121)
                            {
                                {
                                    {
                                        bamsyntax->ac4_stereo_channel_mode = ac4_value;
                                        err = BAM_sink->after_assign_int(BAM_sink,"stereo_channel_mode", bamsyntax->ac4_stereo_channel_mode);
                                        if (err != BAM_OK)
                                        {
                                            return err;
                                        }
                                    }
                                    {
                                        ac4_value = 2;
                                        err = BAM_sink->after_assign_int(BAM_sink,"value", ac4_value);
                                        if (err != BAM_OK)
                                        {
                                            return err;
                                        }
                                    }
                                }
                            }
                            if (ac4_value == 126)
                            {
                                {
                                    {
                                        err = BAM_source->read_uint(BAM_source, 1, &bamsyntax->ac4_v);
                                        if (err != BAM_OK)
                                        {
                                            return err;
                                        }
                                        bamsyntax->BAM_g_position += 1;
                                        err = BAM_sink->write_uint(BAM_sink, "v", 1, bamsyntax->ac4_v);
                                        if (err != BAM_OK)
                                        {
                                            return err;
                                        }
                                    }
                                    {
                                        ac4_value = (ac4_value << 1) + bamsyntax->ac4_v;
                                        err = BAM_sink->after_assign_int(BAM_sink,"value", ac4_value);
                                        if (err != BAM_OK)
                                        {
                                            return err;
                                        }
                                    }
                                }
                            }
                            if (ac4_value == 127)
                            {
                                {
                                    {
                                        err = BAM_source->read_uint(BAM_source, 2, &bamsyntax->ac4_v);
                                        if (err != BAM_OK)
                                        {
                                            return err;
                                        }
                                        bamsyntax->BAM_g_position += 2;
                                        err = BAM_sink->write_uint(BAM_sink, "v", 2, bamsyntax->ac4_v);
                                        if (err != BAM_OK)
                                        {
                                            return err;
                                        }
                                    }
                                    {
                                        ac4_value = (ac4_value << 2) + bamsyntax->ac4_v;
                                        err = BAM_sink->after_assign_int(BAM_sink,"value", ac4_value);
                                        if (err != BAM_OK)
                                        {
                                            return err;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    *BAM_result =  ac4_value;
    {
    }
    return BAM_OK;
    return BAM_OK;
}

