bam_error F_ac4_bitrate_indicator_reset(struct BAMSyntax * BAM_Syntax)
{
    err = reset_state(BAM_Syntax);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
bam_error F_ac4_bitrate_indicator_set_input(struct BAMSyntax * BAM_Syntax, struct BAMVector * param_vector)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_Syntax;
    (void) bamsyntax;
    bamsyntax->BAM_user_args = param_vector;
    return BAM_OK;
}
bam_error F_ac4_bitrate_indicator_parse_generic(struct BAMSyntax * BAM_syntax, struct BAMSource * BAM_source, struct BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    err = F_ac4_bitrate_indicator_parse(BAM_syntax, BAM_source, BAM_sink);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
BAMint F_ac4_bitrate_indicator_get_result(struct BAMSyntax * BAM_syntax)
{
    return BAM_FUNCTION_ERROR;
}
bam_error F_ac4_bitrate_indicator_parse(BAMSyntax  * BAM_syntax, BAMSource * BAM_source, BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    BAMint ac4_bi;
    BAMint ac4_factor;
    int BAM_bool;

    (void) BAM_bool;
    struct BAMVector * BAM_g_table12= BAMVector_create(sizeof(BAMint), 0);
    err = BAMVector_push_vector_int(BAM_g_table12, 0);
    if (err != BAM_OK)
    {
        return err;
    }
    err = BAMVector_push_vector_int(BAM_g_table12, 2);
    if (err != BAM_OK)
    {
        return err;
    }
    err = BAMVector_push_vector_int(BAM_g_table12, 4);
    if (err != BAM_OK)
    {
        return err;
    }
    err = BAMVector_push_vector_int(BAM_g_table12, 6);
    if (err != BAM_OK)
    {
        return err;
    }
    struct BAMVector * BAM_l_tmp_vector16 = BAMVector_create(sizeof(BAMint), 0);
    (void) BAM_l_tmp_vector16;
    {
        err = BAM_source->read_uint(BAM_source, 3, &ac4_bi);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 3;
        err = BAM_sink->write_uint(BAM_sink, "bi", 3, ac4_bi);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    if (BAMVector_find(BAM_g_table12, ac4_bi))
    {
        {
            ac4_bi = ac4_bi >> 1;
            err = BAM_sink->after_assign_int(BAM_sink,"bi", ac4_bi);
            if (err != BAM_OK)
            {
                return err;
            }
        }
    }
    else
    {
        {
            err = BAM_source->read_uint(BAM_source, 2, &bamsyntax->ac4_v);
            if (err != BAM_OK)
            {
                return err;
            }
            bamsyntax->BAM_g_position += 2;
            err = BAM_sink->write_uint(BAM_sink, "v", 2, bamsyntax->ac4_v);
            if (err != BAM_OK)
            {
                return err;
            }
        }
        {
            bamsyntax->ac4_v = (ac4_bi << 2) + bamsyntax->ac4_v;
            err = BAM_sink->after_assign_int(BAM_sink,"v", bamsyntax->ac4_v);
            if (err != BAM_OK)
            {
                return err;
            }
        }
        {
            ac4_factor = bamsyntax->ac4_v / 8;
            err = BAM_sink->after_assign_int(BAM_sink,"factor", ac4_factor);
            if (err != BAM_OK)
            {
                return err;
            }
        }
        {
            ac4_bi = bamsyntax->ac4_v - ac4_factor * 4;
            err = BAM_sink->after_assign_int(BAM_sink,"bi", ac4_bi);
            if (err != BAM_OK)
            {
                return err;
            }
        }
    }
    BAMVector_destroy(BAM_l_tmp_vector16, 1);
    BAMVector_destroy(BAM_g_table12, 1);
    return BAM_OK;
}

