    BAMVector_destroy(bamsyntax->ac4_group_frame_rate_fraction, 1);
    BAMVector_destroy(bamsyntax->ac4_group_to_oamd, 1);
    BAMVector_destroy(bamsyntax->ac4_group_to_presentation, 1);
    BAMVector_destroy(bamsyntax->ac4_group_to_substreams, 2);
