    BAMVector_destroy(bamsyntax->ac4_raw_ch_mod_grp, 2);
    BAMVector_destroy(bamsyntax->ac4_referenced_substreams, 1);
    BAMVector_destroy(bamsyntax->ac4_si_b_iframe, 1);
