    BAMVector_destroy(bamsyntax->ac4_substreams_object_type_BED, 2);
    BAMVector_destroy(bamsyntax->ac4_substreams_object_type_DYNAMIC, 2);
    BAMVector_destroy(bamsyntax->ac4_substreams_object_type_ISF, 2);
    BAMVector_destroy(bamsyntax->ac4_top_channels_present_array, 1);
    free (self);
