bam_error F_ac4_content_type_parse(BAMSyntax  * BAM_syntax, BAMSource * BAM_source, BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    BAMint ac4_b_language_indicator;
    BAMint ac4_b_serialized_language_tag;
    BAMint ac4_language_tag_bytes;
    BAMint ac4_b_start_tag;
    BAMint ac4_n_language_tag_bytes;
    BAMint ac4_language_tag_chunk;
    int BAM_bool;

    (void) BAM_bool;
    {
        err = BAM_source->read_uint(BAM_source, 3, &bamsyntax->ac4_content_classifier);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 3;
        err = BAM_sink->write_uint(BAM_sink, "content_classifier", 3, bamsyntax->ac4_content_classifier);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    {
        err = BAM_source->read_uint(BAM_source, 1, &ac4_b_language_indicator);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 1;
        err = BAM_sink->write_uint(BAM_sink, "b_language_indicator", 1, ac4_b_language_indicator);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    if (ac4_b_language_indicator)
    {
        {
            {
                err = BAM_source->read_uint(BAM_source, 1, &ac4_b_serialized_language_tag);
                if (err != BAM_OK)
                {
                    return err;
                }
                bamsyntax->BAM_g_position += 1;
                err = BAM_sink->write_uint(BAM_sink, "b_serialized_language_tag", 1, ac4_b_serialized_language_tag);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            if (ac4_b_serialized_language_tag)
            {
                {
                    {
                        err = BAM_source->read_uint(BAM_source, 1, &ac4_b_start_tag);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                        bamsyntax->BAM_g_position += 1;
                        err = BAM_sink->write_uint(BAM_sink, "b_start_tag", 1, ac4_b_start_tag);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                    }
                    {
                        err = BAM_source->read_uint(BAM_source, 16, &ac4_language_tag_chunk);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                        bamsyntax->BAM_g_position += 16;
                        err = BAM_sink->write_uint(BAM_sink, "language_tag_chunk", 16, ac4_language_tag_chunk);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                    }
                }
            }
            else
            {
                {
                    err = BAM_source->read_uint(BAM_source, 6, &ac4_n_language_tag_bytes);
                    if (err != BAM_OK)
                    {
                        return err;
                    }
                    bamsyntax->BAM_g_position += 6;
                    err = BAM_sink->write_uint(BAM_sink, "n_language_tag_bytes", 6, ac4_n_language_tag_bytes);
                    if (err != BAM_OK)
                    {
                        return err;
                    }
                }
                for (bamsyntax->ac4_i = 0; bamsyntax->ac4_i < ac4_n_language_tag_bytes; bamsyntax->ac4_i++)
                {
                    err = BAM_source->read_uint(BAM_source, 8, &ac4_language_tag_bytes);
                    if (err != BAM_OK)
                    {
                        return err;
                    }
                    bamsyntax->BAM_g_position += 8;
                    err = BAM_sink->write_uint(BAM_sink, "language_tag_bytes", 8, ac4_language_tag_bytes);
                    if (err != BAM_OK)
                    {
                        return err;
                    }
                }
            }
        }
    }
    return BAM_OK;
}

