bam_error F_ac4_ac4_hsf_ext_substream_info_parse(BAMSyntax  * BAM_syntax, BAMint ac4_ahsf_b_substreams_present, BAMSource * BAM_source, BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    int BAM_bool;

    (void) BAM_bool;
    if (ac4_ahsf_b_substreams_present == 1)
    {
        {
            {
                err = BAM_source->read_uint(BAM_source, 2, &bamsyntax->ac4_substream_index);
                if (err != BAM_OK)
                {
                    return err;
                }
                bamsyntax->BAM_g_position += 2;
                err = BAM_sink->write_uint(BAM_sink, "substream_index", 2, bamsyntax->ac4_substream_index);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            if (bamsyntax->ac4_substream_index == 3)
            {
                {
                    {
                        BAMVector_push_vector_parameter(bamsyntax->BAM_internal_args, BAMParameter_create_int(2));
                        err = BAM_sink->before_call(BAM_sink, "variable_bits", bamsyntax->BAM_internal_args, "v");
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                        err = BAMVector_clear_parameter(bamsyntax->BAM_internal_args);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                        err = F_ac4_variable_bits_parse(&bamsyntax->ac4_v, BAM_syntax, 2, BAM_source, BAM_sink);
                        if(err != BAM_OK)
                        {
                            return err;
                        }
                        err = BAM_sink->after_call_int(BAM_sink, "variable_bits", "v", bamsyntax->ac4_v);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                    }
                    {
                        bamsyntax->ac4_substream_index += bamsyntax->ac4_v;
                        err = BAM_sink->after_assign_int(BAM_sink,"substream_index", bamsyntax->ac4_substream_index);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                    }
                }
            }
        }
    }
    else
    {
        {
            bamsyntax->ac4_substream_index = bamsyntax->ac4_bk_substream_index;
            err = BAM_sink->after_assign_int(BAM_sink,"substream_index", bamsyntax->ac4_substream_index);
            if (err != BAM_OK)
            {
                return err;
            }
        }
        {
            bamsyntax->ac4_bk_substream_index = bamsyntax->ac4_bk_substream_index + 1;
            err = BAM_sink->after_assign_int(BAM_sink,"bk_substream_index", bamsyntax->ac4_bk_substream_index);
            if (err != BAM_OK)
            {
                return err;
            }
        }
    }
    {
        /* allocate 'bamsyntax->ac4_substream_type' up to index 'bamsyntax->ac4_substream_index' */
        if ((BAMint) BAMVector_size(bamsyntax->ac4_substream_type) < bamsyntax->ac4_substream_index + 1)
        {
            err = BAMVector_resize_vector_string(bamsyntax->ac4_substream_type, bamsyntax->ac4_substream_index + 1);
            if (err != BAM_OK)
            {
                return err;
            }
        }
        BAMVector_data_string(bamsyntax->ac4_substream_type)[bamsyntax->ac4_substream_index] = "hsf";
        err = BAM_sink->after_assign_string(BAM_sink,"substream_type[substream_index]", BAMVector_data_string(bamsyntax->ac4_substream_type)[bamsyntax->ac4_substream_index]);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    if (ac4_ahsf_b_substreams_present == 1)
    {
        {
            {
                bamsyntax->ac4_last_referenced_substream = ((BAMint)bamsyntax->ac4_last_referenced_substream > (BAMint)bamsyntax->ac4_substream_index) ? (BAMint)bamsyntax->ac4_last_referenced_substream : (BAMint)bamsyntax->ac4_substream_index;
                err = BAM_sink->after_assign_int(BAM_sink,"last_referenced_substream", bamsyntax->ac4_last_referenced_substream);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                err = BAMVector_push_vector_int(bamsyntax->ac4_referenced_substreams, bamsyntax->ac4_substream_index);
                if (err != BAM_OK)
                {
                    return err;
                }
                err = BAM_sink->after_assign_vector_int(BAM_sink,"referenced_substreams", bamsyntax->ac4_referenced_substreams);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
        }
    }
    return BAM_OK;
}

