bam_error F_ac4_presentation_config_ext_info_parse(BAMSyntax  * BAM_syntax, BAMSource * BAM_source, BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    int BAM_bool;

    (void) BAM_bool;
    {
        err = BAM_source->read_uint(BAM_source, 5, &bamsyntax->ac4_n_skip_bytes);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 5;
        err = BAM_sink->write_uint(BAM_sink, "n_skip_bytes", 5, bamsyntax->ac4_n_skip_bytes);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    {
        err = BAM_source->read_uint(BAM_source, 1, &bamsyntax->ac4_b_more_skip_bytes);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 1;
        err = BAM_sink->write_uint(BAM_sink, "b_more_skip_bytes", 1, bamsyntax->ac4_b_more_skip_bytes);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    if (bamsyntax->ac4_b_more_skip_bytes)
    {
        {
            {
                BAMVector_push_vector_parameter(bamsyntax->BAM_internal_args, BAMParameter_create_int(2));
                err = BAM_sink->before_call(BAM_sink, "variable_bits", bamsyntax->BAM_internal_args, "v");
                if (err != BAM_OK)
                {
                    return err;
                }
                err = BAMVector_clear_parameter(bamsyntax->BAM_internal_args);
                if (err != BAM_OK)
                {
                    return err;
                }
                err = F_ac4_variable_bits_parse(&bamsyntax->ac4_v, BAM_syntax, 2, BAM_source, BAM_sink);
                if(err != BAM_OK)
                {
                    return err;
                }
                err = BAM_sink->after_call_int(BAM_sink, "variable_bits", "v", bamsyntax->ac4_v);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                bamsyntax->ac4_n_skip_bytes += bamsyntax->ac4_v << 5;
                err = BAM_sink->after_assign_int(BAM_sink,"n_skip_bytes", bamsyntax->ac4_n_skip_bytes);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
        }
    }
    if (0)
    {
        {
            {
                bamsyntax->ac4_n_bits_read_0 = bamsyntax->BAM_g_position;
                err = BAM_sink->after_assign_int(BAM_sink,"n_bits_read_0", bamsyntax->ac4_n_bits_read_0);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                BAMVector_push_vector_parameter(bamsyntax->BAM_internal_args, BAMParameter_create_int(bamsyntax->ac4_toc_i));
                err = BAM_sink->before_call(BAM_sink, "ac4_presentation_v2_info", bamsyntax->BAM_internal_args, NULL);
                if (err != BAM_OK)
                {
                    return err;
                }
                err = BAMVector_clear_parameter(bamsyntax->BAM_internal_args);
                if (err != BAM_OK)
                {
                    return err;
                }
                err = F_ac4_ac4_presentation_v2_info_parse(BAM_syntax, bamsyntax->ac4_toc_i, BAM_source, BAM_sink);
                if(err != BAM_OK)
                {
                    return err;
                }
                err = BAM_sink->after_call_void(BAM_sink, "ac4_presentation_v2_info");
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                bamsyntax->ac4_n_bits_read_1 = bamsyntax->BAM_g_position;
                err = BAM_sink->after_assign_int(BAM_sink,"n_bits_read_1", bamsyntax->ac4_n_bits_read_1);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                bamsyntax->ac4_n_bits_read = bamsyntax->ac4_n_bits_read_1 - bamsyntax->ac4_n_bits_read_0;
                err = BAM_sink->after_assign_int(BAM_sink,"n_bits_read", bamsyntax->ac4_n_bits_read);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            if ((((bamsyntax->ac4_n_bits_read) < 0) == ((8) < 0) ? ((bamsyntax->ac4_n_bits_read) % (8)) : (((bamsyntax->ac4_n_bits_read) % (8)) + (8)) % (8)))
            {
                {
                    {
                        bamsyntax->ac4_n_skip_bits = 8 - (((bamsyntax->ac4_n_bits_read) < 0) == ((8) < 0) ? ((bamsyntax->ac4_n_bits_read) % (8)) : (((bamsyntax->ac4_n_bits_read) % (8)) + (8)) % (8));
                        err = BAM_sink->after_assign_int(BAM_sink,"n_skip_bits", bamsyntax->ac4_n_skip_bits);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                    }
                    {
                        err = BAM_source->read_uint(BAM_source, bamsyntax->ac4_n_skip_bits, &bamsyntax->ac4_reserved);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                        bamsyntax->BAM_g_position += bamsyntax->ac4_n_skip_bits;
                        err = BAM_sink->write_uint(BAM_sink, "reserved", bamsyntax->ac4_n_skip_bits, bamsyntax->ac4_reserved);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                    }
                    {
                        bamsyntax->ac4_n_bits_read += bamsyntax->ac4_n_skip_bits;
                        err = BAM_sink->after_assign_int(BAM_sink,"n_bits_read", bamsyntax->ac4_n_bits_read);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                    }
                }
            }
            {
                bamsyntax->ac4_n_skip_bytes = bamsyntax->ac4_n_skip_bytes - bamsyntax->ac4_n_bits_read / 8;
                err = BAM_sink->after_assign_int(BAM_sink,"n_skip_bytes", bamsyntax->ac4_n_skip_bytes);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
        }
    }
    if (bamsyntax->ac4_bitstream_version >= 1 && bamsyntax->ac4_presentation_config == 8)
    {
        {
            {
                bamsyntax->ac4_n_bits_read_0 = bamsyntax->BAM_g_position;
                err = BAM_sink->after_assign_int(BAM_sink,"n_bits_read_0", bamsyntax->ac4_n_bits_read_0);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                err = BAM_sink->before_call(BAM_sink, "personalization_info", bamsyntax->BAM_internal_args, NULL);
                if (err != BAM_OK)
                {
                    return err;
                }
                err = BAMVector_clear_parameter(bamsyntax->BAM_internal_args);
                if (err != BAM_OK)
                {
                    return err;
                }
                err = F_ac4_personalization_info_parse(BAM_syntax, BAM_source, BAM_sink);
                if(err != BAM_OK)
                {
                    return err;
                }
                err = BAM_sink->after_call_void(BAM_sink, "personalization_info");
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                bamsyntax->ac4_n_bits_read_1 = bamsyntax->BAM_g_position;
                err = BAM_sink->after_assign_int(BAM_sink,"n_bits_read_1", bamsyntax->ac4_n_bits_read_1);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                err = BAM_source->read_uint(BAM_source, bamsyntax->ac4_n_skip_bytes * 8 - (bamsyntax->ac4_n_bits_read_1 - bamsyntax->ac4_n_bits_read_0), &bamsyntax->ac4_padding);
                if (err != BAM_OK)
                {
                    return err;
                }
                bamsyntax->BAM_g_position += bamsyntax->ac4_n_skip_bytes * 8 - (bamsyntax->ac4_n_bits_read_1 - bamsyntax->ac4_n_bits_read_0);
                err = BAM_sink->write_uint(BAM_sink, "padding", bamsyntax->ac4_n_skip_bytes * 8 - (bamsyntax->ac4_n_bits_read_1 - bamsyntax->ac4_n_bits_read_0), bamsyntax->ac4_padding);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
        }
    }
    else
    for (bamsyntax->ac4_i = 0; bamsyntax->ac4_i < bamsyntax->ac4_n_skip_bytes; bamsyntax->ac4_i++)
    {
        err = BAM_source->read_uint(BAM_source, 8, &bamsyntax->ac4_reserved);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 8;
        err = BAM_sink->write_uint(BAM_sink, "reserved", 8, bamsyntax->ac4_reserved);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    return BAM_OK;
}

