{
    return BAM_FUNCTION_ERROR;
}
bam_error F_ac4_emdf_info_parse(BAMSyntax  * BAM_syntax, BAMSource * BAM_source, BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    BAMint ac4_key_id;
    BAMint ac4_emdf_version;
    BAMint ac4_b_emdf_payloads_substream_info;
    int BAM_bool;

    (void) BAM_bool;
    {
        err = BAM_source->read_uint(BAM_source, 2, &ac4_emdf_version);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 2;
        err = BAM_sink->write_uint(BAM_sink, "emdf_version", 2, ac4_emdf_version);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    if (ac4_emdf_version == 3)
    {
        {
            {
                BAMVector_push_vector_parameter(bamsyntax->BAM_internal_args, BAMParameter_create_int(2));
                err = BAM_sink->before_call(BAM_sink, "variable_bits", bamsyntax->BAM_internal_args, "v");
                if (err != BAM_OK)
                {
                    return err;
                }
                err = BAMVector_clear_parameter(bamsyntax->BAM_internal_args);
                if (err != BAM_OK)
                {
                    return err;
                }
                err = F_ac4_variable_bits_parse(&bamsyntax->ac4_v, BAM_syntax, 2, BAM_source, BAM_sink);
                if(err != BAM_OK)
                {
                    return err;
                }
                err = BAM_sink->after_call_int(BAM_sink, "variable_bits", "v", bamsyntax->ac4_v);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                ac4_emdf_version += bamsyntax->ac4_v;
                err = BAM_sink->after_assign_int(BAM_sink,"emdf_version", ac4_emdf_version);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
        }
    }
    {
        err = BAM_source->read_uint(BAM_source, 3, &ac4_key_id);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 3;
        err = BAM_sink->write_uint(BAM_sink, "key_id", 3, ac4_key_id);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    if (ac4_key_id == 7)
    {
        {
            {
                BAMVector_push_vector_parameter(bamsyntax->BAM_internal_args, BAMParameter_create_int(3));
                err = BAM_sink->before_call(BAM_sink, "variable_bits", bamsyntax->BAM_internal_args, "v");
                if (err != BAM_OK)
                {
                    return err;
                }
                err = BAMVector_clear_parameter(bamsyntax->BAM_internal_args);
                if (err != BAM_OK)
                {
                    return err;
                }
                err = F_ac4_variable_bits_parse(&bamsyntax->ac4_v, BAM_syntax, 3, BAM_source, BAM_sink);
                if(err != BAM_OK)
                {
                    return err;
                }
                err = BAM_sink->after_call_int(BAM_sink, "variable_bits", "v", bamsyntax->ac4_v);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                ac4_key_id += bamsyntax->ac4_v;
                err = BAM_sink->after_assign_int(BAM_sink,"key_id", ac4_key_id);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
        }
    }
    {
        err = BAM_source->read_uint(BAM_source, 1, &ac4_b_emdf_payloads_substream_info);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 1;
        err = BAM_sink->write_uint(BAM_sink, "b_emdf_payloads_substream_info", 1, ac4_b_emdf_payloads_substream_info);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    if (ac4_b_emdf_payloads_substream_info)
    {
        {
            BAMVector_push_vector_parameter(bamsyntax->BAM_internal_args, BAMParameter_create_int(bamsyntax->ac4_toc_i));
            err = BAM_sink->before_call(BAM_sink, "emdf_payloads_substream_info", bamsyntax->BAM_internal_args, NULL);
            if (err != BAM_OK)
            {
                return err;
            }
            err = BAMVector_clear_parameter(bamsyntax->BAM_internal_args);
            if (err != BAM_OK)
            {
                return err;
            }
            err = F_ac4_emdf_payloads_substream_info_parse(BAM_syntax, bamsyntax->ac4_toc_i, BAM_source, BAM_sink);
            if(err != BAM_OK)
            {
                return err;
            }
            err = BAM_sink->after_call_void(BAM_sink, "emdf_payloads_substream_info");
            if (err != BAM_OK)
            {
                return err;
            }
        }
    }
    {
        err = BAM_sink->before_call(BAM_sink, "emdf_protection", bamsyntax->BAM_internal_args, NULL);
        if (err != BAM_OK)
        {
            return err;
        }
        err = BAMVector_clear_parameter(bamsyntax->BAM_internal_args);
        if (err != BAM_OK)
        {
            return err;
        }
        err = F_emdf_protection_parse(BAM_syntax, BAM_source, BAM_sink);
        if(err != BAM_OK)
        {
            return err;
        }
        err = BAM_sink->after_call_void(BAM_sink, "emdf_protection");
        if (err != BAM_OK)
        {
            return err;
        }
    }
    return BAM_OK;
}

