{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    err = F_ac4_emdf_payloads_substream_info_parse(BAM_syntax, BAMParameter_as_int(BAMVector_data_parameter(bamsyntax->BAM_user_args)[0]), BAM_source, BAM_sink);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
