bam_error F_emdf_protection_reset(struct BAMSyntax * BAM_Syntax)
{
    err = reset_state(BAM_Syntax);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
bam_error F_emdf_protection_set_input(struct BAMSyntax * BAM_Syntax, struct BAMVector * param_vector)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_Syntax;
    (void) bamsyntax;
    bamsyntax->BAM_user_args = param_vector;
    return BAM_OK;
}
bam_error F_emdf_protection_parse_generic(struct BAMSyntax * BAM_syntax, struct BAMSource * BAM_source, struct BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    err = F_emdf_protection_parse(BAM_syntax, BAM_source, BAM_sink);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
BAMint F_emdf_protection_get_result(struct BAMSyntax * BAM_syntax)
{
    return BAM_FUNCTION_ERROR;
}
bam_error F_emdf_protection_parse(BAMSyntax  * BAM_syntax, BAMSource * BAM_source, BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    BAMint emdf_protection_bits_primary;
    BAMint emdf_protection_length_secondary;
    BAMint emdf_protection_length_primary;
    BAMint emdf_protection_bits_secondary;
    int BAM_bool;

    (void) BAM_bool;
    {
        err = BAM_source->read_uint(BAM_source, 2, &emdf_protection_length_primary);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 2;
        err = BAM_sink->write_uint(BAM_sink, "protection_length_primary", 2, emdf_protection_length_primary);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    {
        err = BAM_source->read_uint(BAM_source, 2, &emdf_protection_length_secondary);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 2;
        err = BAM_sink->write_uint(BAM_sink, "protection_length_secondary", 2, emdf_protection_length_secondary);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    if ((emdf_protection_length_primary) == (0))
    {
        if (1)
        {
            return BAM_RESERVED_VALUE;
        }
    }
    else if ((emdf_protection_length_primary) == (1))
    {
        {
            bamsyntax->emdf_protection_bits_primary_bits = 8;
            err = BAM_sink->after_assign_int(BAM_sink,"protection_bits_primary_bits", bamsyntax->emdf_protection_bits_primary_bits);
            if (err != BAM_OK)
            {
                return err;
            }
        }
    }
    else if ((emdf_protection_length_primary) == (2))
    {
        {
            bamsyntax->emdf_protection_bits_primary_bits = 32;
            err = BAM_sink->after_assign_int(BAM_sink,"protection_bits_primary_bits", bamsyntax->emdf_protection_bits_primary_bits);
            if (err != BAM_OK)
            {
                return err;
            }
        }
    }
    else if ((emdf_protection_length_primary) == (3))
    {
        {
            bamsyntax->emdf_protection_bits_primary_bits = 128;
            err = BAM_sink->after_assign_int(BAM_sink,"protection_bits_primary_bits", bamsyntax->emdf_protection_bits_primary_bits);
            if (err != BAM_OK)
            {
                return err;
            }
        }
    }
    {
        err = BAM_source->read_uint(BAM_source, bamsyntax->emdf_protection_bits_primary_bits, &emdf_protection_bits_primary);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += bamsyntax->emdf_protection_bits_primary_bits;
        err = BAM_sink->write_uint(BAM_sink, "protection_bits_primary", bamsyntax->emdf_protection_bits_primary_bits, emdf_protection_bits_primary);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    if ((emdf_protection_length_secondary) == (0))
    {
        {
            bamsyntax->emdf_protection_bits_secondary_bits = 0;
            err = BAM_sink->after_assign_int(BAM_sink,"protection_bits_secondary_bits", bamsyntax->emdf_protection_bits_secondary_bits);
            if (err != BAM_OK)
            {
                return err;
            }
        }
    }
    else if ((emdf_protection_length_secondary) == (1))
    {
        {
            bamsyntax->emdf_protection_bits_secondary_bits = 8;
            err = BAM_sink->after_assign_int(BAM_sink,"protection_bits_secondary_bits", bamsyntax->emdf_protection_bits_secondary_bits);
            if (err != BAM_OK)
            {
                return err;
            }
        }
    }
    else if ((emdf_protection_length_secondary) == (2))
    {
        {
            bamsyntax->emdf_protection_bits_secondary_bits = 32;
            err = BAM_sink->after_assign_int(BAM_sink,"protection_bits_secondary_bits", bamsyntax->emdf_protection_bits_secondary_bits);
            if (err != BAM_OK)
            {
                return err;
            }
        }
    }
    else if ((emdf_protection_length_secondary) == (3))
    {
        {
            bamsyntax->emdf_protection_bits_secondary_bits = 128;
            err = BAM_sink->after_assign_int(BAM_sink,"protection_bits_secondary_bits", bamsyntax->emdf_protection_bits_secondary_bits);
            if (err != BAM_OK)
            {
                return err;
            }
        }
    }
    {
        err = BAM_source->read_uint(BAM_source, bamsyntax->emdf_protection_bits_secondary_bits, &emdf_protection_bits_secondary);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += bamsyntax->emdf_protection_bits_secondary_bits;
        err = BAM_sink->write_uint(BAM_sink, "protection_bits_secondary", bamsyntax->emdf_protection_bits_secondary_bits, emdf_protection_bits_secondary);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    return BAM_OK;
}

