bam_error F_ac4_define_oamd_reset(struct BAMSyntax * BAM_Syntax)
{
    err = reset_state(BAM_Syntax);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
bam_error F_ac4_define_oamd_set_input(struct BAMSyntax * BAM_Syntax, struct BAMVector * param_vector)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_Syntax;
    (void) bamsyntax;
    bamsyntax->BAM_user_args = param_vector;
    return BAM_OK;
}
bam_error F_ac4_define_oamd_parse_generic(struct BAMSyntax * BAM_syntax, struct BAMSource * BAM_source, struct BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    err = F_ac4_define_oamd_parse(BAM_syntax, BAM_source, BAM_sink);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
BAMint F_ac4_define_oamd_get_result(struct BAMSyntax * BAM_syntax)
{
    return BAM_FUNCTION_ERROR;
}
bam_error F_ac4_define_oamd_parse(BAMSyntax  * BAM_syntax, BAMSource * BAM_source, BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    int BAM_bool;

    (void) BAM_bool;
    {
        bamsyntax->ac4_OAMD_OBJECT_TYPE_BED = 0;
        err = BAM_sink->after_assign_int(BAM_sink,"OAMD_OBJECT_TYPE_BED", bamsyntax->ac4_OAMD_OBJECT_TYPE_BED);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    {
        bamsyntax->ac4_OAMD_OBJECT_TYPE_ISF = 1;
        err = BAM_sink->after_assign_int(BAM_sink,"OAMD_OBJECT_TYPE_ISF", bamsyntax->ac4_OAMD_OBJECT_TYPE_ISF);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    {
        bamsyntax->ac4_OAMD_OBJECT_TYPE_DYNAMIC = 2;
        err = BAM_sink->after_assign_int(BAM_sink,"OAMD_OBJECT_TYPE_DYNAMIC", bamsyntax->ac4_OAMD_OBJECT_TYPE_DYNAMIC);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    {
        bamsyntax->ac4_OAMD_OBJECT_TYPE_RESERVED = 3;
        err = BAM_sink->after_assign_int(BAM_sink,"OAMD_OBJECT_TYPE_RESERVED", bamsyntax->ac4_OAMD_OBJECT_TYPE_RESERVED);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    {
        bamsyntax->ac4_NUM_TRIM_CONFIGS = 9;
        err = BAM_sink->after_assign_int(BAM_sink,"NUM_TRIM_CONFIGS", bamsyntax->ac4_NUM_TRIM_CONFIGS);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    return BAM_OK;
}

