bam_error F_ac4_oamd_substream_info_reset(struct BAMSyntax * BAM_Syntax)
{
    err = reset_state(BAM_Syntax);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
bam_error F_ac4_oamd_substream_info_set_input(struct BAMSyntax * BAM_Syntax, struct BAMVector * param_vector)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_Syntax;
    (void) bamsyntax;
    bamsyntax->BAM_user_args = param_vector;
    return BAM_OK;
}
bam_error F_ac4_oamd_substream_info_parse_generic(struct BAMSyntax * BAM_syntax, struct BAMSource * BAM_source, struct BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    err = F_ac4_oamd_substream_info_parse(BAM_syntax, BAMParameter_as_int(BAMVector_data_parameter(bamsyntax->BAM_user_args)[0]), BAM_source, BAM_sink);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
BAMint F_ac4_oamd_substream_info_get_result(struct BAMSyntax * BAM_syntax)
{
    return BAM_FUNCTION_ERROR;
}
bam_error F_ac4_oamd_substream_info_parse(BAMSyntax  * BAM_syntax, BAMint ac4_oamd_b_substreams_present, BAMSource * BAM_source, BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    BAMint ac4_b_iframe_oamd;
    struct BAMVector * ac4_b_iframe = BAMVector_create(sizeof(BAMint), 0);
    (void) ac4_b_iframe;
    int BAM_bool;

    (void) BAM_bool;
    {
        err = BAM_sink->before_call(BAM_sink, "define_oamd", bamsyntax->BAM_internal_args, NULL);
        if (err != BAM_OK)
        {
            return err;
        }
        err = BAMVector_clear_parameter(bamsyntax->BAM_internal_args);
        if (err != BAM_OK)
        {
            return err;
        }
        err = F_ac4_define_oamd_parse(BAM_syntax, BAM_source, BAM_sink);
        if(err != BAM_OK)
        {
            return err;
        }
        err = BAM_sink->after_call_void(BAM_sink, "define_oamd");
        if (err != BAM_OK)
        {
            return err;
        }
    }
    {
        err = BAM_source->read_uint(BAM_source, 1, &ac4_b_iframe_oamd);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 1;
        err = BAM_sink->write_uint(BAM_sink, "b_iframe_oamd", 1, ac4_b_iframe_oamd);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    if (ac4_oamd_b_substreams_present == 1)
    {
        {
            {
                err = BAM_source->read_uint(BAM_source, 2, &bamsyntax->ac4_substream_index);
                if (err != BAM_OK)
                {
                    return err;
                }
                bamsyntax->BAM_g_position += 2;
                err = BAM_sink->write_uint(BAM_sink, "substream_index", 2, bamsyntax->ac4_substream_index);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            if (bamsyntax->ac4_substream_index == 3)
            {
                {
                    {
                        BAMVector_push_vector_parameter(bamsyntax->BAM_internal_args, BAMParameter_create_int(2));
                        err = BAM_sink->before_call(BAM_sink, "variable_bits", bamsyntax->BAM_internal_args, "vb");
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                        err = BAMVector_clear_parameter(bamsyntax->BAM_internal_args);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                        err = F_ac4_variable_bits_parse(&bamsyntax->ac4_vb, BAM_syntax, 2, BAM_source, BAM_sink);
                        if(err != BAM_OK)
                        {
                            return err;
                        }
                        err = BAM_sink->after_call_int(BAM_sink, "variable_bits", "vb", bamsyntax->ac4_vb);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                    }
                    {
                        bamsyntax->ac4_substream_index += bamsyntax->ac4_vb;
                        err = BAM_sink->after_assign_int(BAM_sink,"substream_index", bamsyntax->ac4_substream_index);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                    }
                }
            }
        }
    }
    else
    {
        {
            bamsyntax->ac4_substream_index = bamsyntax->ac4_bk_substream_index;
            err = BAM_sink->after_assign_int(BAM_sink,"substream_index", bamsyntax->ac4_substream_index);
            if (err != BAM_OK)
            {
                return err;
            }
        }
        {
            bamsyntax->ac4_bk_substream_index = bamsyntax->ac4_bk_substream_index + 1;
            err = BAM_sink->after_assign_int(BAM_sink,"bk_substream_index", bamsyntax->ac4_bk_substream_index);
            if (err != BAM_OK)
            {
                return err;
            }
        }
    }
    {
        /* allocate 'bamsyntax->ac4_substream_type' up to index 'bamsyntax->ac4_substream_index' */
        if ((BAMint) BAMVector_size(bamsyntax->ac4_substream_type) < bamsyntax->ac4_substream_index + 1)
        {
            err = BAMVector_resize_vector_string(bamsyntax->ac4_substream_type, bamsyntax->ac4_substream_index + 1);
            if (err != BAM_OK)
            {
                return err;
            }
        }
        BAMVector_data_string(bamsyntax->ac4_substream_type)[bamsyntax->ac4_substream_index] = "oamd";
        err = BAM_sink->after_assign_string(BAM_sink,"substream_type[substream_index]", BAMVector_data_string(bamsyntax->ac4_substream_type)[bamsyntax->ac4_substream_index]);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    {
        /* allocate 'bamsyntax->ac4_num_channels_array' up to index 'bamsyntax->ac4_substream_index' */
        if ((BAMint) BAMVector_size(bamsyntax->ac4_num_channels_array) < bamsyntax->ac4_substream_index + 1)
        {
            err = BAMVector_resize_vector_int(bamsyntax->ac4_num_channels_array, bamsyntax->ac4_substream_index + 1);
            if (err != BAM_OK)
            {
                return err;
            }
        }
        BAMVector_data_int(bamsyntax->ac4_num_channels_array)[bamsyntax->ac4_substream_index] = 0;
        err = BAM_sink->after_assign_int(BAM_sink,"num_channels_array[substream_index]", BAMVector_data_int(bamsyntax->ac4_num_channels_array)[bamsyntax->ac4_substream_index]);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    if (ac4_oamd_b_substreams_present == 1)
    {
        {
            {
                bamsyntax->ac4_last_referenced_substream = ((BAMint)bamsyntax->ac4_last_referenced_substream > (BAMint)bamsyntax->ac4_substream_index) ? (BAMint)bamsyntax->ac4_last_referenced_substream : (BAMint)bamsyntax->ac4_substream_index;
                err = BAM_sink->after_assign_int(BAM_sink,"last_referenced_substream", bamsyntax->ac4_last_referenced_substream);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                err = BAMVector_push_vector_int(bamsyntax->ac4_referenced_substreams, bamsyntax->ac4_substream_index);
                if (err != BAM_OK)
                {
                    return err;
                }
                err = BAM_sink->after_assign_vector_int(BAM_sink,"referenced_substreams", bamsyntax->ac4_referenced_substreams);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
        }
    }
    {
        /* allocate 'ac4_b_iframe' up to index 'bamsyntax->ac4_substream_index' */
        if ((BAMint) BAMVector_size(ac4_b_iframe) < bamsyntax->ac4_substream_index + 1)
        {
            err = BAMVector_resize_vector_int(ac4_b_iframe, bamsyntax->ac4_substream_index + 1);
            if (err != BAM_OK)
            {
                return err;
            }
        }
        BAMVector_data_int(ac4_b_iframe)[bamsyntax->ac4_substream_index] = ac4_b_iframe_oamd;
        err = BAM_sink->after_assign_int(BAM_sink,"b_iframe[substream_index]", BAMVector_data_int(ac4_b_iframe)[bamsyntax->ac4_substream_index]);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    BAMVector_destroy(ac4_b_iframe, 1);
    return BAM_OK;
}

