bam_error F_ac4_stereo_dmx_coeff_reset(struct BAMSyntax * BAM_Syntax)
{
    err = reset_state(BAM_Syntax);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
bam_error F_ac4_stereo_dmx_coeff_set_input(struct BAMSyntax * BAM_Syntax, struct BAMVector * param_vector)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_Syntax;
    (void) bamsyntax;
    bamsyntax->BAM_user_args = param_vector;
    return BAM_OK;
}
bam_error F_ac4_stereo_dmx_coeff_parse_generic(struct BAMSyntax * BAM_syntax, struct BAMSource * BAM_source, struct BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    err = F_ac4_stereo_dmx_coeff_parse(BAM_syntax, BAM_source, BAM_sink);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
BAMint F_ac4_stereo_dmx_coeff_get_result(struct BAMSyntax * BAM_syntax)
{
    return BAM_FUNCTION_ERROR;
}
bam_error F_ac4_stereo_dmx_coeff_parse(BAMSyntax  * BAM_syntax, BAMSource * BAM_source, BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    BAMint ac4_b_ltrt_mixinfo;
    BAMint ac4_ltrt_centre_mixgain;
    BAMint ac4_loro_centre_mixgain;
    BAMint ac4_b_lfe_mixinfo;
    BAMint ac4_preferred_dmx_method;
    BAMint ac4_ltrt_surround_mixgain;
    BAMint ac4_loro_surround_mixgain;
    BAMint ac4_lfe_mixgain;
    int BAM_bool;

    (void) BAM_bool;
    {
        err = BAM_source->read_uint(BAM_source, 3, &ac4_loro_centre_mixgain);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 3;
        err = BAM_sink->write_uint(BAM_sink, "loro_centre_mixgain", 3, ac4_loro_centre_mixgain);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    {
        err = BAM_source->read_uint(BAM_source, 3, &ac4_loro_surround_mixgain);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 3;
        err = BAM_sink->write_uint(BAM_sink, "loro_surround_mixgain", 3, ac4_loro_surround_mixgain);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    {
        err = BAM_source->read_uint(BAM_source, 1, &ac4_b_ltrt_mixinfo);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 1;
        err = BAM_sink->write_uint(BAM_sink, "b_ltrt_mixinfo", 1, ac4_b_ltrt_mixinfo);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    if (ac4_b_ltrt_mixinfo == 1)
    {
        {
            {
                err = BAM_source->read_uint(BAM_source, 3, &ac4_ltrt_centre_mixgain);
                if (err != BAM_OK)
                {
                    return err;
                }
                bamsyntax->BAM_g_position += 3;
                err = BAM_sink->write_uint(BAM_sink, "ltrt_centre_mixgain", 3, ac4_ltrt_centre_mixgain);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                err = BAM_source->read_uint(BAM_source, 3, &ac4_ltrt_surround_mixgain);
                if (err != BAM_OK)
                {
                    return err;
                }
                bamsyntax->BAM_g_position += 3;
                err = BAM_sink->write_uint(BAM_sink, "ltrt_surround_mixgain", 3, ac4_ltrt_surround_mixgain);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
        }
    }
    {
        err = BAM_source->read_uint(BAM_source, 1, &ac4_b_lfe_mixinfo);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 1;
        err = BAM_sink->write_uint(BAM_sink, "b_lfe_mixinfo", 1, ac4_b_lfe_mixinfo);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    if (ac4_b_lfe_mixinfo == 1)
    {
        {
            err = BAM_source->read_uint(BAM_source, 5, &ac4_lfe_mixgain);
            if (err != BAM_OK)
            {
                return err;
            }
            bamsyntax->BAM_g_position += 5;
            err = BAM_sink->write_uint(BAM_sink, "lfe_mixgain", 5, ac4_lfe_mixgain);
            if (err != BAM_OK)
            {
                return err;
            }
        }
    }
    {
        err = BAM_source->read_uint(BAM_source, 2, &ac4_preferred_dmx_method);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 2;
        err = BAM_sink->write_uint(BAM_sink, "preferred_dmx_method", 2, ac4_preferred_dmx_method);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    return BAM_OK;
}

