bam_error F_ac4_tool_tb_to_f_s_parse(BAMSyntax  * BAM_syntax, BAMSource * BAM_source, BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    BAMint ac4_gain_t2e_code;
    BAMint ac4_gain_t2d_code;
    BAMint ac4_b_top_back_to_front;
    int BAM_bool;

    (void) BAM_bool;
    {
        err = BAM_source->read_uint(BAM_source, 1, &ac4_b_top_back_to_front);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 1;
        err = BAM_sink->write_uint(BAM_sink, "b_top_back_to_front", 1, ac4_b_top_back_to_front);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    if (ac4_b_top_back_to_front == 1)
    {
        {
            {
                err = BAM_source->read_uint(BAM_source, 3, &ac4_gain_t2d_code);
                if (err != BAM_OK)
                {
                    return err;
                }
                bamsyntax->BAM_g_position += 3;
                err = BAM_sink->write_uint(BAM_sink, "gain_t2d_code", 3, ac4_gain_t2d_code);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                ac4_gain_t2e_code = 7;
                err = BAM_sink->after_assign_int(BAM_sink,"gain_t2e_code", ac4_gain_t2e_code);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
        }
    }
    else
    {
        err = BAM_source->read_uint(BAM_source, 3, &ac4_gain_t2e_code);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 3;
        err = BAM_sink->write_uint(BAM_sink, "gain_t2e_code", 3, ac4_gain_t2e_code);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    return BAM_OK;
}

