bam_error F_ac4_common_headphone_md_reset(struct BAMSyntax * BAM_Syntax)
{
    err = reset_state(BAM_Syntax);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
bam_error F_ac4_common_headphone_md_set_input(struct BAMSyntax * BAM_Syntax, struct BAMVector * param_vector)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_Syntax;
    (void) bamsyntax;
    bamsyntax->BAM_user_args = param_vector;
    return BAM_OK;
}
bam_error F_ac4_common_headphone_md_parse_generic(struct BAMSyntax * BAM_syntax, struct BAMSource * BAM_source, struct BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    err = F_ac4_common_headphone_md_parse(BAM_syntax, BAM_source, BAM_sink);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
BAMint F_ac4_common_headphone_md_get_result(struct BAMSyntax * BAM_syntax)
{
    return BAM_FUNCTION_ERROR;
}
bam_error F_ac4_common_headphone_md_parse(BAMSyntax  * BAM_syntax, BAMSource * BAM_source, BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    BAMint ac4_b_hp_md_present;
    BAMint ac4_hp_operation_mode;
    BAMint ac4_b_head_track_disable_all;
    int BAM_bool;

    (void) BAM_bool;
    {
        err = BAM_source->read_uint(BAM_source, 1, &ac4_b_hp_md_present);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 1;
        err = BAM_sink->write_uint(BAM_sink, "b_hp_md_present", 1, ac4_b_hp_md_present);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    if (ac4_b_hp_md_present)
    {
        {
            {
                err = BAM_source->read_uint(BAM_source, 3, &ac4_hp_operation_mode);
                if (err != BAM_OK)
                {
                    return err;
                }
                bamsyntax->BAM_g_position += 3;
                err = BAM_sink->write_uint(BAM_sink, "hp_operation_mode", 3, ac4_hp_operation_mode);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            if (ac4_hp_operation_mode == 1 || ac4_hp_operation_mode == 2)
            {
                {
                    err = BAM_source->read_uint(BAM_source, 1, &ac4_b_head_track_disable_all);
                    if (err != BAM_OK)
                    {
                        return err;
                    }
                    bamsyntax->BAM_g_position += 1;
                    err = BAM_sink->write_uint(BAM_sink, "b_head_track_disable_all", 1, ac4_b_head_track_disable_all);
                    if (err != BAM_OK)
                    {
                        return err;
                    }
                }
            }
        }
    }
    return BAM_OK;
}

