bam_error F_ac4_substream_index_table_reset(struct BAMSyntax * BAM_Syntax)
{
    err = reset_state(BAM_Syntax);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
bam_error F_ac4_substream_index_table_set_input(struct BAMSyntax * BAM_Syntax, struct BAMVector * param_vector)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_Syntax;
    (void) bamsyntax;
    bamsyntax->BAM_user_args = param_vector;
    return BAM_OK;
}
bam_error F_ac4_substream_index_table_parse_generic(struct BAMSyntax * BAM_syntax, struct BAMSource * BAM_source, struct BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    err = F_ac4_substream_index_table_parse(BAM_syntax, BAM_source, BAM_sink);
    if (err != BAM_OK)
    {
        return err;
    }
    return BAM_OK;
}
BAMint F_ac4_substream_index_table_get_result(struct BAMSyntax * BAM_syntax)
{
    return BAM_FUNCTION_ERROR;
}
bam_error F_ac4_substream_index_table_parse(BAMSyntax  * BAM_syntax, BAMSource * BAM_source, BAMSink * BAM_sink)
{
    struct syntax * bamsyntax = (struct syntax *) BAM_syntax;
    (void) bamsyntax;
    BAMint ac4_b_size_present;
    struct BAMVector * ac4_b_substream_type_known = BAMVector_create(sizeof(BAMint), 0);
    (void) ac4_b_substream_type_known;
    struct BAMVector * ac4_substream_size = BAMVector_create(sizeof(BAMint), 0);
    (void) ac4_substream_size;
    BAMint ac4_b_more_bits;
    int BAM_bool;

    (void) BAM_bool;
    {
        err = BAM_source->read_uint(BAM_source, 2, &bamsyntax->ac4_n_substreams);
        if (err != BAM_OK)
        {
            return err;
        }
        bamsyntax->BAM_g_position += 2;
        err = BAM_sink->write_uint(BAM_sink, "n_substreams", 2, bamsyntax->ac4_n_substreams);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    if (bamsyntax->ac4_n_substreams == 0)
    {
        {
            {
                BAMVector_push_vector_parameter(bamsyntax->BAM_internal_args, BAMParameter_create_int(2));
                err = BAM_sink->before_call(BAM_sink, "variable_bits", bamsyntax->BAM_internal_args, "v");
                if (err != BAM_OK)
                {
                    return err;
                }
                err = BAMVector_clear_parameter(bamsyntax->BAM_internal_args);
                if (err != BAM_OK)
                {
                    return err;
                }
                err = F_ac4_variable_bits_parse(&bamsyntax->ac4_v, BAM_syntax, 2, BAM_source, BAM_sink);
                if(err != BAM_OK)
                {
                    return err;
                }
                err = BAM_sink->after_call_int(BAM_sink, "variable_bits", "v", bamsyntax->ac4_v);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                bamsyntax->ac4_n_substreams = bamsyntax->ac4_v + 4;
                err = BAM_sink->after_assign_int(BAM_sink,"n_substreams", bamsyntax->ac4_n_substreams);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
        }
    }
    if (bamsyntax->ac4_n_substreams - 1 < bamsyntax->ac4_last_referenced_substream)
    {
        BAMVector_destroy(ac4_b_substream_type_known, 1);
        BAMVector_destroy(ac4_substream_size, 1);
        return BAM_RESERVED_VALUE;
    }
    if (bamsyntax->ac4_n_substreams - 1 > bamsyntax->ac4_last_referenced_substream)
    {
        {
            {
                /* allocate 'ac4_b_substream_type_known' up to index 'bamsyntax->ac4_n_substreams - 1' */
                if ((BAMint) BAMVector_size(ac4_b_substream_type_known) < bamsyntax->ac4_n_substreams - 1 + 1)
                {
                    err = BAMVector_resize_vector_int(ac4_b_substream_type_known, bamsyntax->ac4_n_substreams - 1 + 1);
                    if (err != BAM_OK)
                    {
                        return err;
                    }
                }
                BAMVector_data_int(ac4_b_substream_type_known)[bamsyntax->ac4_n_substreams - 1] = 0;
                err = BAM_sink->after_assign_int(BAM_sink,"b_substream_type_known[n_substreams - 1]", BAMVector_data_int(ac4_b_substream_type_known)[bamsyntax->ac4_n_substreams - 1]);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                /* allocate 'bamsyntax->ac4_substream_type' up to index 'bamsyntax->ac4_n_substreams - 1' */
                if ((BAMint) BAMVector_size(bamsyntax->ac4_substream_type) < bamsyntax->ac4_n_substreams - 1 + 1)
                {
                    err = BAMVector_resize_vector_string(bamsyntax->ac4_substream_type, bamsyntax->ac4_n_substreams - 1 + 1);
                    if (err != BAM_OK)
                    {
                        return err;
                    }
                }
                BAMVector_data_string(bamsyntax->ac4_substream_type)[bamsyntax->ac4_n_substreams - 1] = "unknown";
                err = BAM_sink->after_assign_string(BAM_sink,"substream_type[n_substreams - 1]", BAMVector_data_string(bamsyntax->ac4_substream_type)[bamsyntax->ac4_n_substreams - 1]);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
        }
    }
    if (bamsyntax->ac4_n_substreams == 1)
    {
        {
            err = BAM_source->read_uint(BAM_source, 1, &ac4_b_size_present);
            if (err != BAM_OK)
            {
                return err;
            }
            bamsyntax->BAM_g_position += 1;
            err = BAM_sink->write_uint(BAM_sink, "b_size_present", 1, ac4_b_size_present);
            if (err != BAM_OK)
            {
                return err;
            }
        }
    }
    else
    {
        ac4_b_size_present = 1;
        err = BAM_sink->after_assign_int(BAM_sink,"b_size_present", ac4_b_size_present);
        if (err != BAM_OK)
        {
            return err;
        }
    }
    if (ac4_b_size_present)
    {
        for (bamsyntax->ac4_s = 0; bamsyntax->ac4_s < bamsyntax->ac4_n_substreams; bamsyntax->ac4_s++)
        {
            {
                err = BAM_source->read_uint(BAM_source, 1, &ac4_b_more_bits);
                if (err != BAM_OK)
                {
                    return err;
                }
                bamsyntax->BAM_g_position += 1;
                err = BAM_sink->write_uint(BAM_sink, "b_more_bits", 1, ac4_b_more_bits);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            {
                /* allocate 'ac4_substream_size' up to index 'bamsyntax->ac4_s' */
                if ((BAMint) BAMVector_size(ac4_substream_size) < bamsyntax->ac4_s + 1)
                {
                    err = BAMVector_resize_vector_int(ac4_substream_size, bamsyntax->ac4_s + 1);
                    if (err != BAM_OK)
                    {
                        return err;
                    }
                }
                err = BAM_source->read_uint(BAM_source, 10, &BAMVector_data_int(ac4_substream_size)[bamsyntax->ac4_s]);
                if (err != BAM_OK)
                {
                    return err;
                }
                bamsyntax->BAM_g_position += 10;
                err = BAM_sink->write_uint(BAM_sink, "substream_size[s]", 10, BAMVector_data_int(ac4_substream_size)[bamsyntax->ac4_s]);
                if (err != BAM_OK)
                {
                    return err;
                }
            }
            if (ac4_b_more_bits)
            {
                {
                    {
                        BAMVector_push_vector_parameter(bamsyntax->BAM_internal_args, BAMParameter_create_int(2));
                        err = BAM_sink->before_call(BAM_sink, "variable_bits", bamsyntax->BAM_internal_args, "v");
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                        err = BAMVector_clear_parameter(bamsyntax->BAM_internal_args);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                        err = F_ac4_variable_bits_parse(&bamsyntax->ac4_v, BAM_syntax, 2, BAM_source, BAM_sink);
                        if(err != BAM_OK)
                        {
                            return err;
                        }
                        err = BAM_sink->after_call_int(BAM_sink, "variable_bits", "v", bamsyntax->ac4_v);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                    }
                    {
                        /* allocate 'ac4_substream_size' up to index 'bamsyntax->ac4_s' */
                        if ((BAMint) BAMVector_size(ac4_substream_size) < bamsyntax->ac4_s + 1)
                        {
                            err = BAMVector_resize_vector_int(ac4_substream_size, bamsyntax->ac4_s + 1);
                            if (err != BAM_OK)
                            {
                                return err;
                            }
                        }
                        BAMVector_data_int(ac4_substream_size)[bamsyntax->ac4_s] += bamsyntax->ac4_v << 10;
                        err = BAM_sink->after_assign_int(BAM_sink,"substream_size[s]", BAMVector_data_int(ac4_substream_size)[bamsyntax->ac4_s]);
                        if (err != BAM_OK)
                        {
                            return err;
                        }
                    }
                }
            }
        }
    }
    BAMVector_destroy(ac4_b_substream_type_known, 1);
    BAMVector_destroy(ac4_substream_size, 1);
    return BAM_OK;
}

